'use client';

import { useState } from 'react';
import { generateDonorRecognitionReport } from '@/ai/flows/generate-donor-recognition-report';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Loader2 } from 'lucide-react';

export default function ReportsPage() {
  const [criteria, setCriteria] = useState('Top 5 donors by total donation amount this year.');
  const [report, setReport] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleGenerateReport = async () => {
    try {
      setLoading(true);
      setError('');
      setReport('');
      const result = await generateDonorRecognitionReport({
        criteria,
        reportFormat: 'markdown',
      });
      setReport(result.report);
    } catch (e) {
      console.error(e);
      setError('Failed to generate the report. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid gap-6">
      <Card>
        <CardHeader>
          <CardTitle className="font-headline">Donor Recognition Report</CardTitle>
          <CardDescription>
            Generate custom donor recognition reports using AI.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-2">
            <Label htmlFor="criteria">Report Criteria</Label>
            <Textarea
              id="criteria"
              value={criteria}
              onChange={(e) => setCriteria(e.target.value)}
              placeholder="e.g., Donors who contributed more than $500 to the 'Clean Water Initiative'."
              rows={3}
            />
          </div>
        </CardContent>
        <CardFooter>
          <Button onClick={handleGenerateReport} disabled={loading}>
            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Generate Report
          </Button>
        </CardFooter>
      </Card>
      
      {(loading || error || report) && (
        <Card>
            <CardHeader>
                <CardTitle className="font-headline">Generated Report</CardTitle>
            </CardHeader>
            <CardContent>
            {loading && (
              <div className="flex justify-center items-center py-8">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
              </div>
            )}
            {error && <p className="text-destructive">{error}</p>}
            {report && (
              <div className="prose prose-sm max-w-none rounded-md bg-muted p-4">
                <pre className="whitespace-pre-wrap bg-transparent p-0 font-body">{report}</pre>
              </div>
            )}
            </CardContent>
        </Card>
      )}
    </div>
  );
}
